    spec = stripped[len(RANGE_PREFIX):]

    if ',' in spec:
        raise ValueError("multiple ranges")

    parts = spec.split('-')
    if len(parts) != 2:
        raise ValueError("malformed range")

    first, last = parts

    def validate_int(s):
        if s == '':
            return None
        if not s.isdigit():
            raise ValueError("malformed range")
        return int(s)

    start_val = validate_int(first)
    end_val = validate_int(last)

    if start_val is None and end_val is None:
        raise ValueError("malformed range")

    if start_val is None:
        suffix_len = end_val
        if suffix_len == 0:
            raise ValueError("unsatisfiable range")
        start = max(0, size - suffix_len)
        end = size - 1
    else:
        start = start_val
        if start >= size:
            raise ValueError("unsatisfiable range")
        if end_val is None:
            end = size - 1
        else:
            end = min(end_val, size - 1)
        if start > end:
            raise ValueError("unsatisfiable range")

    return (start, end)
